/**
 * Helper carrying everything an inspector wants to assert against.
 * Populated by inspect_file_dynamic() below.
 */
struct InspectFileResult
{
	bool                   found            = false;
	std::size_t            file_len         = 0;
	std::size_t            data_pages_count = 0;
	std::size_t            inode_data_size  = 0;
	std::size_t            free_data_pages  = 0;
	std::vector<std::byte> contents;
};

/**
 * Re-mount `bin_path` via dynamic::SimpleFlashFsReadOnly (the same
 * read-only inspection wrapper used by `simple_flash_fs_tar -i`) and
 * look up `file_name`. Returns geometry observed on the just-flushed
 * on-disk image.
 *
 * The dynamic FS reads page_size / max_inodes etc. from the header so
 * it can inspect files originally written by the static (ConfigH7) FS.
 */
InspectFileResult inspect_file_dynamic( const std::string & bin_path,
                                        const std::string_view & file_name )
{
	InspectFileResult result;

	if( !std::filesystem::exists( bin_path ) ) {
		CPPDEBUG( Tools::format( "inspect: file does not exist: %s", bin_path ) );
		return result;
	}

	SimFlashFsFlashMemory inspect_mem( bin_path );
	// fully qualify to disambiguate from
	// SimpleFlashFs::static_memory::SimpleFlashFs that is pulled in via
	// `using namespace SimpleFlashFs::static_memory`.
	::SimpleFlashFs::dynamic::SimpleFlashFsReadOnly inspect_fs( &inspect_mem );

	if( !inspect_fs.init() ) {
		CPPDEBUG( Tools::format( "inspect: init failed on %s", bin_path ) );
		return result;
	}

	result.free_data_pages = inspect_fs.get_number_of_free_data_pages();

	// pick the LATEST version of the requested file. A flush creates a
	// new inode page (COW) and the old one is only erased lazily, so
	// get_all_inodes() can return multiple versions of the same
	// inode_number with the same file_name. The on-disk current view
	// is the one with the highest inode_version_number.
	decltype( inspect_fs.get_all_inodes( false ) )::value_type latest{};

	for( auto inode : inspect_fs.get_all_inodes( false ) ) {
		if( inode->inode.file_name.empty() ) {
			continue;
		}
		if( inode->inode.file_name != file_name ) {
			continue;
		}
		if( !latest ||
		    inode->inode.inode_version_number >
		        latest->inode.inode_version_number ) {
			latest = inode;
		}
	}

	if( latest ) {
		result.found            = true;
		result.file_len         = latest->inode.file_len;
		result.data_pages_count = latest->inode.data_pages.size();
		result.inode_data_size  = latest->inode.inode_data.size();

		// pull out the actual bytes for content verification
		if( latest->inode.file_len > 0 ) {
			result.contents.resize( latest->inode.file_len );
			latest->seek( 0 );
			std::size_t bytes_read =
				latest->read( result.contents.data(), result.contents.size() );
			result.contents.resize( bytes_read );
		}
	}

	return result;
}

/**
 * Common scaffolding identical to TestCaseOpenBase in test_static_open.cc
 * but lives in this TU so we can run a per-test functor that has full
 * access to both the live fs and the underlying bin file name.
 */
class TestCaseTruncate : public TestCaseBase<bool>
{
public:
	using Func = std::function<bool( SimpleFsNoDel<ConfigH7> & fs,
	                                 const std::string &       bin_file )>;

protected:
	std::optional<SimpleFsNoDel<ConfigH7>>                       fs;
	std::optional<::SimpleFlashFs::SimPc::SimFlashFsFlashMemory> mem;
	std::string                                                  file_name;
	Func                                                         func;

public:
	TestCaseTruncate( const std::string & name_, Func func_ )
	: TestCaseBase<bool>( name_, true ),
	  func( func_ )
	{
		file_name = "." + name + ".bin";
	}

	bool run() override
	{
		if( std::filesystem::exists( file_name ) ) {
			if( !std::filesystem::remove( file_name ) ) {
				throw STDERR_EXCEPTION(
					Tools::format( "cannot delete %s", file_name ) );
			}
		}

		mem.emplace( file_name, SFF_MAX_SIZE );
		fs.emplace( &mem.value() );

		if( !fs->init() ) {
			if( !fs->create() ) {
				throw STDERR_EXCEPTION(
					Tools::format( "cannot create %s", file_name ) );
			}
		}

		bool ret = false;
		try {
			ret = func( *fs, file_name );
		} catch( ... ) {
			fs.reset();
			mem.reset();
			throw;
		}

		// drop the writer first so the file is flushed/closed before
		// the inspector mounts it again in the test body if needed
		fs.reset();
		mem.reset();
		return ret;
	}
};

constexpr const char *  k_test_file_name = "trunc.test";
constexpr std::size_t   k_inline_size    = 100;
constexpr std::size_t   k_inline_grown   = 300;
constexpr std::size_t   k_large_size     = 4 * SFF_PAGE_SIZE + 123; // 5 data pages
constexpr std::size_t   k_shrink_target  = 1 * SFF_PAGE_SIZE + 50;  // 2 data pages

bool check_zero_padding( const std::vector<std::byte> & contents,
                         std::size_t                     from,
                         std::size_t                     to,
                         const char *                    label )
{
	for( std::size_t i = from; i < to; i++ ) {
		if( contents[i] != std::byte( 0 ) ) {
			CPPDEBUG( Tools::format(
				"%s: expected zero at offset %d, got 0x%02X", label, i,
				static_cast<unsigned>( contents[i] ) ) );
			return false;
		}
	}
	return true;
}

bool check_filler( const std::vector<std::byte> & contents,
                   std::size_t                     from,
                   std::size_t                     to,
                   std::byte                       expected,
                   const char *                    label )
{
	for( std::size_t i = from; i < to; i++ ) {
		if( contents[i] != expected ) {
			CPPDEBUG( Tools::format(
				"%s: expected 0x%02X at offset %d, got 0x%02X", label,
				static_cast<unsigned>( expected ), i,
				static_cast<unsigned>( contents[i] ) ) );
			return false;
		}
	}
	return true;
}

