/**
 * Enlarge an inline-stored file. Verifies the new bytes are zero-filled
 * and the file is still inline (no external data pages).
 */
std::shared_ptr<TestCaseBase<bool>> test_case_static_truncate_enlarge()
{
	return std::make_shared<TestCaseTruncate>(
		__FUNCTION__,
		[]( SimpleFsNoDel<ConfigH7> & fs, const std::string & bin_file ) {
			{
				auto f = fs.open( k_test_file_name,
				                  std::ios_base::out | std::ios_base::trunc );
				if( !f ) {
					CPPDEBUG( "cannot open file" );
					return false;
				}

				std::vector<std::byte> data( k_inline_size, std::byte( 'A' ) );
				if( f.write( data.data(), data.size() ) != data.size() ) {
					CPPDEBUG( "write failed" );
					return false;
				}

				if( !f.truncate( k_inline_grown ) ) {
					CPPDEBUG( "truncate failed" );
					return false;
				}

				if( f.file_size() != k_inline_grown ) {
					CPPDEBUG( Tools::format( "wrong size after truncate: %d",
					                         f.file_size() ) );
					return false;
				}
				// f goes out of scope: flushes
			}

			auto inspect = inspect_file_dynamic( bin_file, k_test_file_name );
			if( !inspect.found ) {
				CPPDEBUG( "inspect: file not found" );
				return false;
			}
			if( inspect.file_len != k_inline_grown ) {
				CPPDEBUG( Tools::format( "inspect: file_len=%d expected %d",
				                         inspect.file_len, k_inline_grown ) );
				return false;
			}
			if( inspect.data_pages_count != 0 ) {
				CPPDEBUG( Tools::format(
					"inspect: data_pages_count=%d expected 0 (inline)",
					inspect.data_pages_count ) );
				return false;
			}
			if( !check_filler( inspect.contents, 0, k_inline_size,
			                   std::byte( 'A' ), "enlarge original" ) ) {
				return false;
			}
			if( !check_zero_padding( inspect.contents, k_inline_size,
			                         k_inline_grown, "enlarge padding" ) ) {
				return false;
			}
			return true;
		} );
}

