/**
 * Shrink a page-stored file. Verifies pages are released to the free
 * pool and the surviving data is still readable.
 */
std::shared_ptr<TestCaseBase<bool>> test_case_static_truncate_shrink_external()
{
	return std::make_shared<TestCaseTruncate>(
		__FUNCTION__,
		[]( SimpleFsNoDel<ConfigH7> & fs, const std::string & bin_file ) {
			std::size_t pages_before = 0;
			std::size_t pages_after  = 0;

			{
				auto f = fs.open( k_test_file_name,
				                  std::ios_base::out | std::ios_base::trunc );
				if( !f ) {
					return false;
				}

				std::vector<std::byte> data( k_large_size, std::byte( 'C' ) );
				if( f.write( data.data(), data.size() ) != data.size() ) {
					return false;
				}
				f.flush();
				pages_before = f.inode.data_pages.size();

				if( pages_before == 0 ) {
					CPPDEBUG( "expected data to land on external pages" );
					return false;
				}

				if( !f.truncate( k_shrink_target ) ) {
					CPPDEBUG( "truncate failed" );
					return false;
				}

				pages_after = f.inode.data_pages.size();

				if( pages_after >= pages_before ) {
					CPPDEBUG( Tools::format(
						"expected pages to shrink, before=%d after=%d",
						pages_before, pages_after ) );
					return false;
				}

				if( f.file_size() != k_shrink_target ) {
					return false;
				}
			}

			auto inspect = inspect_file_dynamic( bin_file, k_test_file_name );
			if( !inspect.found ) {
				return false;
			}
			if( inspect.file_len != k_shrink_target ) {
				CPPDEBUG( Tools::format( "inspect: file_len=%d expected %d",
				                         inspect.file_len, k_shrink_target ) );
				return false;
			}
			if( inspect.data_pages_count != pages_after ) {
				CPPDEBUG( Tools::format(
					"inspect: data_pages_count=%d expected %d",
					inspect.data_pages_count, pages_after ) );
				return false;
			}
			if( inspect.contents.size() != k_shrink_target ) {
				return false;
			}
			if( !check_filler( inspect.contents, 0, k_shrink_target,
			                   std::byte( 'C' ),
			                   "shrink_external content" ) ) {
				return false;
			}
			return true;
		} );
}

/**
 * Write large data on external pages, then truncate to a tiny size
 * that would fit inline. The data stays page-stored (we only trim
 * trailing pages), but file_len shrinks and the visible content
 * matches. Verifies the trim path on pages.
 */
std::shared_ptr<TestCaseBase<bool>>
test_case_static_truncate_shrink_page_to_inline_size()
{
	return std::make_shared<TestCaseTruncate>(
		__FUNCTION__,
		[]( SimpleFsNoDel<ConfigH7> & fs, const std::string & bin_file ) {
			std::size_t pages_before = 0;

			{
				auto f = fs.open( k_test_file_name,
				                  std::ios_base::out | std::ios_base::trunc );
				if( !f ) {
					return false;
				}

				std::vector<std::byte> data( k_large_size, std::byte( 'D' ) );
				if( f.write( data.data(), data.size() ) != data.size() ) {
					return false;
				}
				f.flush();
				pages_before = f.inode.data_pages.size();

				if( pages_before <= 1 ) {
					CPPDEBUG( "expected at least 2 pages before shrink" );
					return false;
				}

				// shrink to something small - 50 bytes
				if( !f.truncate( 50 ) ) {
					return false;
				}

				if( f.file_size() != 50 ) {
					return false;
				}

				// data_pages should be exactly one (covers bytes 0..49)
				if( f.inode.data_pages.size() != 1 ) {
					CPPDEBUG( Tools::format(
						"expected exactly 1 page after shrink, got %d",
						f.inode.data_pages.size() ) );
					return false;
				}
			}

			auto inspect = inspect_file_dynamic( bin_file, k_test_file_name );
			if( !inspect.found ) {
				return false;
			}
			if( inspect.file_len != 50 ) {
				return false;
			}
			if( inspect.data_pages_count != 1 ) {
				CPPDEBUG( Tools::format(
					"inspect: data_pages_count=%d expected 1",
					inspect.data_pages_count ) );
				return false;
			}
			if( inspect.contents.size() != 50 ) {
				return false;
			}
			if( !check_filler( inspect.contents, 0, 50, std::byte( 'D' ),
			                   "shrink page->inline-size content" ) ) {
				return false;
			}
			return true;
		} );
}

